describe("doctests of sympy.functions.special.zeta_functions", () => {
  it("dirichlet_eta(s).rewrite(zeta)", () => {
    const s = new Sym('s');
    expect(sympyStr(rewrite(fn('dirichlet_eta', [s]), 'zeta', { pattern: [], deep: true }))).toBe('Piecewise((log(2), Eq(s, 1)), ((1 - 2**(1 - s))*zeta(s), True))');
  });
  it("expand_func(lerchphi(1, s, a))", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(expandFunc(fn('lerchphi', [rational(1), s, a])))).toBe('zeta(s, a)');
  });
  it("expand_func(lerchphi(-1, s, a))", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(expandFunc(fn('lerchphi', [rational(-1), s, a])))).toBe('zeta(s, a/2)/2**s - zeta(s, a/2 + 1/2)/2**s');
  });
  it("expand_func(lerchphi(z, s, 1))", () => {
    const [z, s] = symbols('z s');
    expect(sympyStr(expandFunc(fn('lerchphi', [z, s, rational(1)])))).toBe('polylog(s, z)/z');
  });
  it("expand_func(lerchphi(z, s, S(1)/2))", () => {
    const [z, s] = symbols('z s');
    expect(sympyStr(expandFunc(fn('lerchphi', [z, s, rational(1, 2)])))).toBe('2**(s - 1)*(polylog(s, sqrt(z))/sqrt(z) - polylog(s, sqrt(z)*exp_polar(I*pi))/sqrt(z))');
  });
  it("expand_func(lerchphi(z, s, S(3)/2))", () => {
    const [z, s] = symbols('z s');
    expect(sympyStr(expandFunc(fn('lerchphi', [z, s, rational(3, 2)])))).toBe('-2**s/z + 2**(s - 1)*(polylog(s, sqrt(z))/sqrt(z) - polylog(s, sqrt(z)*exp_polar(I*pi))/sqrt(z))/z');
  });
  it("lerchphi(z, s, a).diff(z)", () => {
    const [z, s, a] = symbols('z s a');
    expect(sympyStr(diff(fn('lerchphi', [z, s, a]), z))).toBe('(-a*lerchphi(z, s, a) + lerchphi(z, s - 1, a))/z');
  });
  it("lerchphi(z, s, a).diff(a)", () => {
    const [z, s, a] = symbols('z s a');
    expect(sympyStr(diff(fn('lerchphi', [z, s, a]), a))).toBe('-s*lerchphi(z, s + 1, a)');
  });
  it("polylog(s, 0)", () => {
    const s = new Sym('s');
    expect(sympyStr(fn('polylog', [s, rational(0)]))).toBe('0');
  });
  it("polylog(s, 1)", () => {
    const s = new Sym('s');
    expect(sympyStr(fn('polylog', [s, rational(1)]))).toBe('zeta(s)');
  });
  it("polylog(s, -1)", () => {
    const s = new Sym('s');
    expect(sympyStr(fn('polylog', [s, rational(-1)]))).toBe('-dirichlet_eta(s)');
  });
  it("expand_func(polylog(1, z))", () => {
    const z = new Sym('z');
    expect(sympyStr(expandFunc(fn('polylog', [rational(1), z])))).toBe('-log(1 - z)');
  });
  it("expand_func(polylog(0, z))", () => {
    const z = new Sym('z');
    expect(sympyStr(expandFunc(mul(z, pow(add(1, mul(-1, z)), -1))))).toBe('z/(1 - z)');
  });
  it("polylog(s, z).diff(z)", () => {
    const [s, z] = symbols('s z');
    expect(sympyStr(diff(fn('polylog', [s, z]), z))).toBe('polylog(s - 1, z)/z');
  });
  it("polylog(s, z).rewrite(lerchphi)", () => {
    const [s, z] = symbols('s z');
    expect(sympyStr(rewrite(fn('polylog', [s, z]), 'lerchphi', { pattern: [], deep: true }))).toBe('z*lerchphi(z, s, 1)');
  });
  it("riemann_xi(s).rewrite(zeta)", () => {
    const s = new Sym('s');
    expect(sympyStr(rewrite(fn('riemann_xi', [s]), 'zeta', { pattern: [], deep: true }))).toBe('s*(s - 1)*gamma(s/2)*zeta(s)/(2*pi**(s/2))');
  });
  it("stieltjes(n)", () => {
    const n = new Sym('n');
    expect(sympyStr(fn('stieltjes', [n]))).toBe('stieltjes(n)');
  });
  it("stieltjes(0)", () => {
    expect(sympyStr(fn('stieltjes', [rational(0)]))).toBe('EulerGamma');
  });
  it("stieltjes(0, 1)", () => {
    expect(sympyStr(fn('stieltjes', [rational(0), rational(1)]))).toBe('EulerGamma');
  });
  it("stieltjes(n, m)", () => {
    const [n, m] = symbols('n m');
    expect(sympyStr(fn('stieltjes', [n, m]))).toBe('stieltjes(n, m)');
  });
  it("stieltjes(-1)", () => {
    expect(sympyStr(fn('stieltjes', [rational(-1)]))).toBe('zoo');
  });
  it("zeta(s, 1)", () => {
    const s = new Sym('s');
    expect(sympyStr(fn('zeta', [s, rational(1)]))).toBe('zeta(s)');
  });
  it("zeta(s)", () => {
    const s = new Sym('s');
    expect(sympyStr(fn('zeta', [s]))).toBe('zeta(s)');
  });
  it("zeta(s).rewrite(dirichlet_eta)", () => {
    const s = new Sym('s');
    expect(sympyStr(rewrite(fn('zeta', [s]), 'dirichlet_eta', { pattern: [], deep: true }))).toBe('dirichlet_eta(s)/(1 - 2**(1 - s))');
  });
  it("zeta(2)", () => {
    expect(sympyStr(fn('zeta', [rational(2)]))).toBe('pi**2/6');
  });
  it("zeta(4)", () => {
    expect(sympyStr(fn('zeta', [rational(4)]))).toBe('pi**4/90');
  });
  it("zeta(0)", () => {
    expect(sympyStr(fn('zeta', [rational(0)]))).toBe('-1/2');
  });
  it("zeta(-1)", () => {
    expect(sympyStr(fn('zeta', [rational(-1)]))).toBe('-1/12');
  });
  it("zeta(-4)", () => {
    expect(sympyStr(fn('zeta', [rational(-4)]))).toBe('0');
  });
  it("zeta(3).n()", () => {
    expect(sympyStr(fn('zeta', [rational(3)]).evalf(15, {}))).toBe('1.20205690315959');
  });
  it("zeta(s, a).diff(a)", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(diff(fn('zeta', [s, a]), a))).toBe('-s*zeta(s + 1, a)');
  });
  it("zeta(s, a).diff(s)", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(diff(fn('zeta', [s, a]), s))).toBe('Derivative(zeta(s, a), s)');
  });
  it("zeta(s, a).rewrite(lerchphi)", () => {
    const [s, a] = symbols('s a');
    expect(sympyStr(rewrite(fn('zeta', [s, a]), 'lerchphi', { pattern: [], deep: true }))).toBe('lerchphi(1, s, a)');
  });
});

